WITH RECURSIVE ancestors(leaf_id,category_id,parent_category_id,path) AS (SELECT c.category_id,c.category_id,c.parent_category_id,c.category_id::VARCHAR FROM categories c WHERE NOT EXISTS(SELECT 1 FROM categories child WHERE child.parent_category_id=c.category_id) UNION ALL SELECT a.leaf_id,c.category_id,c.parent_category_id,a.path||'>'||c.category_id::VARCHAR FROM ancestors a JOIN categories c ON c.category_id=a.parent_category_id) SELECT leaf_id,path FROM ancestors WHERE parent_category_id IS NULL ORDER BY leaf_id;
